def _sig_f(x): return 1.0 / (1.0 + fnp.exp(-x))
def _gelu_f(x): return 0.5 * x * (1.0 + fnp.tanh(0.7978845608 * (x + 0.044715 * x * x * x)))

def _op_bhat_fnp(traj_raw, W, need_depth):
    """traj_raw: (K,n,10) fnp; W: list of fnp (n,n). -> b_hat (n,) at need_depth. fnp GRU, board-safe."""
    n = int(W[0].shape[0]); d = _GD
    trajN = (traj_raw - _TMU) / _TSD
    dmu = fnp.zeros(n); dv = fnp.zeros(n); h = fnp.zeros((n, d))
    for m in range(2, int(need_depth) + 1):
        Wm = W[m - 1]; Phi = traj_raw[m - 1, :, 2]
        prop_mu = Phi * (Wm.T @ dmu); prop_v = (Wm * Wm).T @ dv
        x = fnp.concatenate([trajN[m - 1], prop_mu[:, None], prop_v[:, None]], axis=-1)
        gi = x @ _WIH + _BIH; gh = h @ _WHH + _BHH
        ir = gi[:, :d]; iz = gi[:, d:2 * d]; in_ = gi[:, 2 * d:]
        hr = gh[:, :d]; hz = gh[:, d:2 * d]; hn = gh[:, 2 * d:]
        rr = _sig_f(ir + hr); zz = _sig_f(iz + hz); nn = fnp.tanh(in_ + rr * hn)
        h = (1.0 - zz) * nn + zz * h
        e = _gelu_f(h @ _R0W + _R0B) @ _R2W + _R2B
        dmu = e[:, 0]; dv = e[:, 1]
    return dmu * _SIGMU


# ===== F=14 operator: numpy-free op_bhat_multi (validated vs PyTorch, max 1e-5, board-safe) =====
def _opw_load(opw, k):
    import base64 as _b64, array as _arr
    sh, b = opw[k]; f = _arr.array('f'); f.frombytes(_b64.b64decode(b)); f = f.tolist()
    if len(sh) == 1:
        return fasarray(f, dtype=fnp.float32)
    return fasarray([f[i * sh[1]:(i + 1) * sh[1]] for i in range(sh[0])], dtype=fnp.float32)


def _sig_m(x):
    return 1.0 / (1.0 + fnp.exp(-x))


def _gelu_m(x):
    return 0.5 * x * (1.0 + fnp.tanh(0.7978845608 * (x + 0.044715 * x * x * x)))


def op_bhat_multi(traj_raw, W, need_depth, opw):
    n = int(W[0].shape[0]); d = opw["GD"]; L = opw["L"]; sig_mu = opw["sig_mu"]
    TMU = _opw_load(opw, "tmu"); TSD = _opw_load(opw, "tsd")
    WIH = [_opw_load(opw, "WIH%d" % i) for i in range(L)]; WHH = [_opw_load(opw, "WHH%d" % i) for i in range(L)]
    BIH = [_opw_load(opw, "BIH%d" % i) for i in range(L)]; BHH = [_opw_load(opw, "BHH%d" % i) for i in range(L)]
    R0W = _opw_load(opw, "R0W"); R0B = _opw_load(opw, "R0B"); R2W = _opw_load(opw, "R2W"); R2B = _opw_load(opw, "R2B")
    trajN = (traj_raw - TMU) / TSD; dmu = fnp.zeros(n); dv = fnp.zeros(n); hs = [fnp.zeros((n, d)) for _ in range(L)]
    for m in range(2, int(need_depth) + 1):
        Wm = W[m - 1]; Phi = traj_raw[m - 1, :, 2]
        prop_mu = Phi * (Wm.T @ dmu); prop_v = (Wm * Wm).T @ dv
        inp = fnp.concatenate([trajN[m - 1], prop_mu[:, None], prop_v[:, None]], axis=-1)
        for i in range(L):
            gi = inp @ WIH[i] + BIH[i]; gh = hs[i] @ WHH[i] + BHH[i]
            rr = _sig_m(gi[:, :d] + gh[:, :d]); zz = _sig_m(gi[:, d:2 * d] + gh[:, d:2 * d])
            nn = fnp.tanh(gi[:, 2 * d:] + rr * gh[:, 2 * d:])
            hs[i] = (1.0 - zz) * nn + zz * hs[i]; inp = hs[i]
        e = _gelu_m(hs[-1] @ R0W + R0B) @ R2W + R2B; dmu = e[:, 0]; dv = e[:, 1]
    return dmu * sig_mu



_GELU_STD_M = (0.7978845608, 0.044715)
_GELU_MINIMAX_M = (0.8001570785481045, 0.04336760164053798)

def _build_fast_m(opw):
    d = opw["GD"]; L = opw["L"]
    schema = opw.get("schema")
    if schema is None:
        assert opw.get("arch", "v3") == "v3", "explicit non-V3 arch requires tagged schema"
        arch, gelu, gelu_ab = "v3", "tanh", _GELU_STD_M
    else:
        assert schema == "sol-tagged-opw-v2", f"unsupported operator schema {schema!r}"
        arch, gelu = opw.get("arch"), opw.get("gelu")
        gelu_ab = (opw.get("gelu_a"), opw.get("gelu_b"))
    assert arch in ("v3", "v3i", "v3ih", "v3im_tanh"), f"unsupported operator arch {arch!r}"
    assert gelu in ("tanh", "tanh_minimax", "erf_nr"), f"unsupported operator GELU {gelu!r}"
    if gelu == "tanh":
        assert gelu_ab == _GELU_STD_M, f"unrecognized tanh GELU coefficients {gelu_ab!r}"
    elif gelu == "tanh_minimax":
        assert gelu_ab == _GELU_MINIMAX_M, f"unrecognized minimax GELU coefficients {gelu_ab!r}"
    else:
        assert gelu_ab == (None, None), f"erf GELU must not carry tanh coefficients {gelu_ab!r}"
    assert arch != "v3im_tanh" or gelu == "tanh", "v3im_tanh requires tanh GELU"
    feature_variant = opw.get("feature_variant", "full_closure_legacy")
    switch_depth = int(opw.get("switch_depth", -1))
    label_variant = opw.get("label_variant", "legacy_unspecified")
    feature_meta_sha256 = opw.get("feature_meta_sha256", "")
    label_meta_sha256 = opw.get("label_meta_sha256", "")
    if feature_variant == "full_through_switch_then_s1":
        assert schema == "sol-tagged-opw-v2", "S1 requires tagged OPW schema"
        assert switch_depth == 18, f"canonical delayed-S1 runtime supports switch 18 only, got {switch_depth}"
        assert label_variant == "plain_rebased", f"unsupported S1 label variant {label_variant!r}"
        for key, value in (("feature_meta_sha256", feature_meta_sha256),
                           ("label_meta_sha256", label_meta_sha256)):
            assert isinstance(value, str) and len(value) == 64                 and all(c in "0123456789abcdef" for c in value), f"invalid {key}"
    else:
        assert feature_variant in ("full_closure", "full_closure_legacy"),             f"operator feature variant {feature_variant!r} needs a matching closure runtime"
        assert switch_depth == -1, f"full closure carries switch_depth={switch_depth}"
    fw = {"d": d, "L": L, "sig_mu": opw["sig_mu"], "arch": arch,
          "gelu": gelu, "gelu_a": gelu_ab[0], "gelu_b": gelu_ab[1],
          "gelu_ab": None if gelu_ab[0] is None else gelu_ab[0] * gelu_ab[1],
          "schema": schema, "feature_variant": feature_variant, "switch_depth": switch_depth,
          "static_affine_serialized": bool(opw.get("static_affine_serialized", False)),
          "label_variant": label_variant, "feature_meta_sha256": feature_meta_sha256,
          "label_meta_sha256": label_meta_sha256}
    fw["TMU"] = _opw_load(opw, "tmu"); fw["TSD"] = _opw_load(opw, "tsd")
    WIH = _opw_load(opw, "WIH0"); WHH = _opw_load(opw, "WHH0")
    BHH = _opw_load(opw, "BHH0")
    fw["WIHp0"] = WIH[-2:]
    assert fw["static_affine_serialized"], "tagged release requires serialized static affine"
    fw["WITN0"] = _opw_load(opw, "WITN0"); fw["GIB0"] = _opw_load(opw, "GIB0")
    fw["WHH0"] = WHH; fw["Bhn0"] = BHH[2 * d:]
    fw["R0W"] = _opw_load(opw, "R0W"); fw["R0B"] = _opw_load(opw, "R0B")
    fw["R2W"] = _opw_load(opw, "R2W"); fw["R2B"] = _opw_load(opw, "R2B")
    return fw


def _erf_nr_m(x):
    z = fnp.abs(x); t = 1.0 / (1.0 + 0.5 * z); p = 0.17087277
    for c in (-0.82215223, 1.48851587, -1.13520398, 0.27886807,
              -0.18628806, 0.09678418, 0.37409196, 1.00002368):
        p = c + t * p
    tau = t * fnp.exp(-z * z - 1.26551223 + t * p)
    return fnp.where(x >= 0.0, 1.0 - tau, tau - 1.0)


def _gelu_erf_m(x):
    return 0.5 * x * (1.0 + _erf_nr_m(x * 0.7071067811865476))


def op_bhat_fast_m(traj_raw, W, W2, need_depth, fw):
    n = int(W[0].shape[0]); d = fw["d"]
    arch = fw["arch"]
    mean_innovation = arch in ("v3i", "v3ih")
    additive_variance = arch == "v3i"
    mean_only = arch == "v3im_tanh"
    use_erf = fw["gelu"] == "erf_nr"
    GIT = traj_raw @ fw["WITN0"] + fw["GIB0"]
    dmu = fzeros(n); h = fzeros((n, d))
    dv = None if mean_only else fzeros(n)
    for m in range(2, int(need_depth) + 1):
        Wm = W[m - 1]; Phi = traj_raw[m - 1, :, 2]
        prop_mu = Phi * (dmu @ Wm)
        if mean_only:
            gi = GIT[m - 1] + prop_mu[:, None] @ fw["WIHp0"][:1]
        else:
            prop_v = dv @ W2[m - 1]
            props = fnp.stack([prop_mu, prop_v], axis=1)
            gi = GIT[m - 1] + props @ fw["WIHp0"]
        gh = h @ fw["WHH0"]
        s_rz = _sig_m(gi[:, :2 * d] + gh[:, :2 * d])
        rr = s_rz[:, :d]; zz = s_rz[:, d:]
        nn = fnp.tanh(gi[:, 2 * d:] + rr * (gh[:, 2 * d:] + fw["Bhn0"]))
        h = zz * (h - nn) + nn
        r0 = h @ fw["R0W"] + fw["R0B"]
        r = r0 * ncdf(r0)
        if mean_only:
            dmu = prop_mu + r @ fw["R2W"][:, 0] + fw["R2B"][0]
        else:
            e = r @ fw["R2W"] + fw["R2B"]
            dmu = prop_mu + e[:, 0] if mean_innovation else e[:, 0]
            dv = prop_v + e[:, 1] if additive_variance else e[:, 1]
        if m in (13, 16, 19, 21):
            fw['dmu' + str(m)] = dmu
    return dmu * fw["sig_mu"]


