# Strassen's rank-7 block scheme (1969) for the sample-forward layer products: each
# recursion level forms the product from 7 block products instead of 8, which is exact in
# real arithmetic. The seven sub-problems are stacked and multiplied as one batched product,
# so a level costs one matrix multiply rather than seven. Operands are zero-padded up to the
# recursion quantum and the padding is sliced off the result.
def _sample_strassen_batched(a, b, levels):
    if levels == 0:
        return fnp.matmul(a, b)

    m2 = int(a.shape[-2]) // 2
    k2 = int(a.shape[-1]) // 2
    n2 = int(b.shape[-1]) // 2

    a11 = a[..., :m2, :k2]
    a12 = a[..., :m2, k2:]
    a21 = a[..., m2:, :k2]
    a22 = a[..., m2:, k2:]
    b11 = b[..., :k2, :n2]
    b12 = b[..., :k2, n2:]
    b21 = b[..., k2:, :n2]
    b22 = b[..., k2:, n2:]

    aa = fnp.stack((
        a11 + a22,
        a21 + a22,
        a11,
        a22,
        a11 + a12,
        a21 - a11,
        a12 - a22,
    ), axis=0)
    bb = fnp.stack((
        b11 + b22,
        b11,
        b12 - b22,
        b21 - b11,
        b22,
        b11 + b12,
        b21 + b22,
    ), axis=0)

    p = _sample_strassen_batched(aa, bb, levels - 1)
    c11 = p[0] + p[3] - p[4] + p[6]
    c12 = p[2] + p[4]
    c21 = p[1] + p[3]
    c22 = p[0] - p[1] + p[2] + p[5]
    return fnp.block([[c11, c12], [c21, c22]])


STRASSEN_LEVELS = 3


def _sample_matmul_strassen(a, b):
    m = int(a.shape[-2])
    k = int(a.shape[-1])
    n = int(b.shape[-1])
    q = 1 << STRASSEN_LEVELS
    mp = ((m + q - 1) // q) * q
    kp = ((k + q - 1) // q) * q
    npad = ((n + q - 1) // q) * q

    if mp != m or kp != k:
        a = fnp.pad(a, ((0, mp - m), (0, kp - k)))
    if kp != k or npad != n:
        b = fnp.pad(b, ((0, kp - k), (0, npad - n)))

    return _sample_strassen_batched(a, b, STRASSEN_LEVELS)[:m, :n]


